  1→"use client";
  2→
  3→/**
  4→ * Renders an AskUserQuestion control request as an interactive question card.
  5→ *
  6→ * Each question shows its options as clickable chips. For single-select
  7→ * questions, clicking an option selects it (deselects others). For
  8→ * multi-select, clicking toggles the option. A single "Submit" button at the
  9→ * bottom sends all answers back to Claude via the control_response flow.
 10→ */
 11→
 12→import { useState } from "react";
 13→import { Button } from "@/components/ui/button";
 14→import type { ChatMessage } from "@/lib/types";
 15→import { cn } from "@/lib/utils";
 16→
 17→export function UserQuestion({
 18→  message,
 19→  onRespond,
 20→}: {
 21→  message: ChatMessage;
 22→  onRespond: (requestId: string, answers: Record<string, string>) => void;
 23→}) {
 24→  const uq = message.userQuestion;
 25→  if (!uq) return null;
 26→
 27→  const questions = uq.questions;
 28→
