"use client";

/**
 * Renders an AskUserQuestion control request as an interactive question card.
 *
 * Each question shows its options as clickable chips. For single-select
 * questions, clicking an option selects it (deselects others). For
 * multi-select, clicking toggles the option. A single "Submit" button at the
 * bottom sends all answers back to Claude via the control_response flow.
 */

import { useState } from "react";
import { Button } from "@/components/ui/button";
import type { ChatMessage } from "@/lib/types";
import { cn } from "@/lib/utils";

export function UserQuestion({
  message,
  onRespond,
}: {
  message: ChatMessage;
  onRespond: (requestId: string, answers: Record<string, string>) => void;
}) {
  const uq = message.userQuestion;
  if (!uq) return null;

  const questions = uq.questions;

  // Lift selection state for all questions into the parent
  const [selections, setSelections] = useState<Map<number, Set<number>>>(
    () => new Map(questions.map((_, i) => [i, new Set<number>()]))
  );

  function toggle(qIdx: number, optIdx: number, multiSelect: boolean) {
    if (uq.resolved) return;
    setSelections((prev) => {
      const next = new Map(prev);
      const sel = new Set(prev.get(qIdx) ?? []);
      if (multiSelect) {
        if (sel.has(optIdx)) sel.delete(optIdx);
        else sel.add(optIdx);
      } else {
        if (sel.has(optIdx)) sel.clear();
        else {
          sel.clear();
          sel.add(optIdx);
        }
      }
      next.set(qIdx, sel);
      return next;
    });
  }

  function handleSubmit() {
    const answers: Record<string, string> = {};
    questions.forEach((q, i) => {
      const sel = selections.get(i) ?? new Set();
      const labels = q.options
        .filter((_, j) => sel.has(j))
        .map((o) => o.label);
      answers[`q${i}`] = labels.join(", ");
    });
    onRespond(uq.requestId, answers);
  }

  // Every question must have at least one selection
  const allAnswered = questions.every(
    (_, i) => (selections.get(i)?.size ?? 0) > 0
  );

  return (
    <div className="mx-auto w-full max-w-lg space-y-4 rounded-lg border-2 border-dashed border-muted-foreground/30 p-3 md:p-4">
      {questions.map((q, i) => (
        <QuestionBlock
          key={i}
          question={q.question}
          header={q.header}
          options={q.options}
          multiSelect={q.multiSelect}
          resolved={uq.resolved}
          selected={selections.get(i) ?? new Set()}
          onToggle={(optIdx) => toggle(i, optIdx, q.multiSelect)}
        />
      ))}
      {!uq.resolved ? (
        <Button size="sm" disabled={!allAnswered} onClick={handleSubmit}>
          Submit
        </Button>
      ) : (
        <div className="text-xs italic text-muted-foreground">Answered</div>
      )}
    </div>
  );
}

function QuestionBlock({
  question,
  header,
  options,
  resolved,
  selected,
  onToggle,
}: {
  question: string;
  header?: string;
  options: { label: string; description?: string }[];
  multiSelect: boolean;
  resolved?: boolean;
  selected: Set<number>;
  onToggle: (optIdx: number) => void;
}) {
  return (
    <div>
      {header && (
        <div className="mb-1 text-xs font-semibold text-muted-foreground">
          {header}
        </div>
      )}
      <div className="mb-3 text-sm">{question}</div>
      <div className="flex flex-wrap gap-2">
        {options.map((opt, i) => (
          <button
            key={i}
            type="button"
            disabled={!!resolved}
            onClick={() => onToggle(i)}
            className={cn(
              "rounded-md border px-3 py-1.5 text-xs transition-colors",
              selected.has(i)
                ? "border-primary bg-primary text-primary-foreground"
                : "border-muted-foreground/30 bg-secondary hover:border-primary/50",
              resolved && "opacity-60 cursor-default"
            )}
            title={opt.description}
          >
            {opt.label}
            {opt.description && (
              <span className="ml-1 text-[10px] opacity-70">
                — {opt.description}
              </span>
            )}
          </button>
        ))}
      </div>
    </div>
  );
}

